#! /usr/bin/env dcli
import 'dart:convert';
import 'dart:io';
import 'package:dcli/dcli.dart';
const repo='/home/bsutton/git/.codex.workspaces/revault-issue-310-zip-read-performance';
const root='$repo/rust/target/secure-arena-reclamation-20261012';
const raw='$repo/docs/evidence/secure-arena-reclamation-2026-10-12/raw/isolated-pressure-profile';
String sha(String p){final r=Process.runSync('/usr/bin/sha256sum',[p]);if(r.exitCode!=0)throw StateError('sha failed $p');return (r.stdout as String).split(RegExp(r'\s+')).first;}
Map<String,Map<String,String>> parse(String p){final text=File(p).readAsStringSync();final packages=<String,Map<String,String>>{};for(final block in text.split('[[package]]').skip(1)){final fields=<String,String>{};for(final key in ['name','version','source','checksum']){final m=RegExp('^$key = "([^"]+)"',multiLine:true).firstMatch(block);if(m!=null)fields[key]=m.group(1)!;}if(!fields.containsKey('name')||!fields.containsKey('version'))throw FormatException('invalid package block in $p');final k=['name','version','source','checksum'].map((x)=>fields[x]??'').join('|');if(packages.containsKey(k))throw FormatException('duplicate package identity $k');packages[k]=fields;}return packages;}
void main(){final original='$raw/original-workspace.Cargo.lock';final paths={'old':'$root/old/rust/revault_page_api/Cargo.lock','new':'$root/new/rust/revault_page_api/Cargo.lock'};final base=parse(original);final variants=<String,Map<String,Map<String,String>>>{};final details=<String,Object>{};for(final e in paths.entries){final resolved=parse(e.value);variants[e.key]=resolved;final absent=resolved.keys.where((k)=>!base.containsKey(k)).toList();details[e.key]={'lock_path':e.value,'sha256':sha(e.value),'package_count':resolved.length,'package_identities':resolved.keys.toList()..sort(),'not_in_original':absent};if(absent.isNotEmpty)throw StateError('${e.key} contains package identities absent from original workspace lock: $absent');}final oldKeys=variants['old']!.keys.toSet();final newKeys=variants['new']!.keys.toSet();final onlyOld=oldKeys.difference(newKeys).toList()..sort();final onlyNew=newKeys.difference(oldKeys).toList()..sort();final result={'original_workspace_lock':{'path':original,'sha256':sha(original),'package_count':base.length},'variants':details,'old_new_resolution_equal':onlyOld.isEmpty&&onlyNew.isEmpty,'only_old':onlyOld,'only_new':onlyNew,'scope':'all locked package name/version/source/checksum identities; no dependency upgrade or source drift accepted'};File('$raw/full-lock-audit.json').writeAsStringSync('${const JsonEncoder.withIndent('  ').convert(result)}\n',flush:true);if(onlyOld.isNotEmpty||onlyNew.isNotEmpty)throw StateError('old/new locked package resolutions differ');print(green('All selected package identities match the original lock; old/new resolutions are equal.'));}
